import unittest
from solution import title_case

class T(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(title_case("hello world"), "Hello World")
    def test_mixed(self):
        self.assertEqual(title_case("hELLO wORLD"), "Hello World")
    def test_single(self):
        self.assertEqual(title_case("x"), "X")
    def test_empty(self):
        self.assertEqual(title_case(""), "")
